// Generated by Viscosity: "ps" stored as a struct of arrays (fields x).
class __Vsc_ps {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_ps(Math.max(16, v.length / 1)); for (let i = 0; i < v.length; i += 1) c.push(v[i + 0]); return c; }
  push(v0) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; }
}
// Generated by Viscosity: "ps" stored as a struct of arrays (fields y, z).
class __Vsc_ps_2 {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.y = new Float64Array(cap); this.z = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_ps_2(Math.max(16, v.length / 2)); for (let i = 0; i < v.length; i += 2) c.push(v[i + 0], v[i + 1]); return c; }
  push(v0, v1) { const n = this.length; if (n === this.cap) this.grow(); this.y[n] = v0; this.z[n] = v1; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.y); this.y = t; t = new Float64Array(cap); t.set(this.z); this.z = t; }
}
// viscosity: ps=soa
function a() {
  const ps = new __Vsc_ps();
  for (let i = 0; i < 100; i++)
    ps.push(i);
  let s = 0;
  for (let i = 0; i < ps.length; i++)
    s += ps.x[i];
  return s;
}
function b() {
  const ps = new __Vsc_ps_2();
  for (let i = 0; i < 100; i++)
    ps.push(i, 1);
  let s = 0;
  for (let i = 0; i < ps.length; i++)
    s += ps.y[i] + ps.z[i];
  return s;
}
